# exact int64 payload of the 2**53+1 ns value, expressed as a delta from the true value
# (0 == exact); a float64 round-trip drops the low bit and yields -1.
for name, op in ops:
    try:
        res = int(op(big, 1.0)._value)
    except Exception:
        res = None
    probe('scalar_' + name + '_payload_delta', 999999 if res is None else res - target)

# do the integral-float ops return Timedelta.min / Timedelta.max unchanged (1) or corrupt/raise (0)?
for name, op in ops:
    for tag, td in [('min', Timedelta.min), ('max', Timedelta.max)]:
        try:
            r = op(td, 1.0)
            ok = 1 if (not pd.isna(r) and int(r._value) == int(td._value)) else 0
        except Exception:
            ok = 0
        probe('scalar_' + name + '_' + tag + '_identity', ok)

